#!/usr/bin/env python3
"""Strip bot / AI-agent attribution lines from a pull-request body.

Reads a markdown file (or stdin with ``-``) and writes the cleaned body to
stdout. Only *whole lines* that look like attribution are dropped; everything
else is preserved byte-for-byte, including indentation and fenced code blocks.

Usage:
    python3 .github/scripts/strip_attribution.py body.md > clean.md
    python3 .github/scripts/strip_attribution.py --check body.md   # exit 1 if dirty
    cat body.md | python3 .github/scripts/strip_attribution.py -

Exit codes:
    0  cleaned body written (whether or not anything was removed)
    1  --check was passed and the body still contains attribution lines

Removed lines are echoed to stderr (prefixed with "stripped:") so the Actions
log shows exactly what changed and why.
"""
from __future__ import annotations

import re
import sys

# Patterns are matched case-insensitively against a single line.
PATTERNS: list[re.Pattern[str]] = [
    # Git trailers: "Co-Authored-By: Claude <noreply@anthropic.com>"
    re.compile(r"^\s*co[-\s]?authored[-\s]?by\s*:", re.I),
    # "Generated with [Claude Code](...)", "Made with Cursor", "Written using Aider"
    re.compile(
        r"\b(generated|created|written|authored|produced|made|crafted|assisted|powered)\b"
        r".{0,60}\b(with|by|using|via)\b.{0,60}"
        # `arena` on its own is not a signature: "arena" is an ordinary word here
        # (the `arena/...` branches) and matching it stripped sentences such as
        # "every commit was made with --no-verify, so none carries an Arena
        # trailer". Require the product name or the account.
        r"\b(claude|cursor|copilot|codex|chatgpt|openai|anthropic|gemini|arena\.ai|"
        r"arena\s+agent(?:\s+mode)?|arena[- ]agent|"
        r"windsurf|aider|devin|replit|bolt\.new|qwen|kimi|grok)\b",
        re.I,
    ),
    # "Built by an AI agent", "Assisted by a bot". "by" must be followed by the
    # role almost immediately, so prose like "`powered by ... bot` rules" survives.
    re.compile(
        r"\b(powered|built|assisted|automated|prepared|maintained)\s+by\s+"
        r"(?:[A-Za-z][\w-]*\s+){0,2}(bot|ai|llm|agent|assistant)\b",
        re.I,
    ),
    # "This PR was generated/opened by <agent>"
    re.compile(
        r"\bthis\s+(pr|pull\s*request|change|patch|commit)\b.{0,60}"
        r"\b(generated|created|made|opened|authored|written|submitted)\b.{0,80}"
        r"\b(ai|bot|agent|assistant|claude|copilot|codex|gpt|arena)\b",
        re.I,
    ),
    # HTML comment attribution: <!-- generated by Claude Code -->
    re.compile(
        r"<!--.{0,300}\b(generated|co[-\s]?authored|claude|copilot|codex|gpt|openai|"
        r"anthropic|arena|bot|agent)\b.{0,300}-->",
        re.I,
    ),
    # The robot emoji is the near-universal prefix of agent footers.
    re.compile(r"\U0001F916"),
]

FENCE = re.compile(r"^\s*(```|~~~)")
SEPARATOR = re.compile(r"^\s*(?:-{3,}|\*{3,}|_{3,})\s*$")


def _inside_code_span(line: str, pos: int) -> bool:
    """True when ``pos`` falls inside an inline code span (odd number of `` ` `` before it)."""
    ticks = 0
    i = 0
    while i < pos:
        if line[i] == "`":
            ticks += 1
        i += 1
    return ticks % 2 == 1


def is_attribution(line: str) -> bool:
    for pattern in PATTERNS:
        for match in pattern.finditer(line):
            # `Co-Authored-By` quoted as an example is documentation, not a trailer.
            if not _inside_code_span(line, match.start()):
                return True
    return False


def clean(text: str) -> tuple[str, list[str]]:
    """Return (cleaned_text, removed_lines)."""
    kept: list[str] = []
    removed: list[str] = []
    in_fence = False

    for line in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if FENCE.match(line):
            in_fence = not in_fence
            kept.append(line)
            continue
        # Never rewrite code samples or quoted raw output.
        if not in_fence and is_attribution(line):
            removed.append(line)
            continue
        kept.append(line)

    # Drop trailing blank/separator lines left behind by removed footers.
    while kept and (not kept[-1].strip() or SEPARATOR.match(kept[-1])):
        kept.pop()

    # Collapse runs of 3+ blank lines that appear after a removal.
    result: list[str] = []
    blanks = 0
    for line in kept:
        if line.strip():
            blanks = 0
        else:
            blanks += 1
            if blanks > 2:
                continue
        result.append(line)

    out = "\n".join(result)
    if out:
        out += "\n"
    return out, removed


def main(argv: list[str]) -> int:
    args = [a for a in argv[1:] if a != "--check"]
    check = "--check" in argv[1:]
    if len(args) != 1:
        print(__doc__.strip().splitlines()[0], file=sys.stderr)
        print("usage: strip_attribution.py [--check] <file|->", file=sys.stderr)
        return 2

    path = args[0]
    text = sys.stdin.read() if path == "-" else open(path, encoding="utf-8").read()

    cleaned, removed = clean(text)
    for line in removed:
        print(f"stripped: {line}", file=sys.stderr)

    if check:
        if removed:
            print(f"{len(removed)} attribution line(s) found", file=sys.stderr)
            return 1
        return 0

    sys.stdout.write(cleaned)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
